/** Adds two numbers. */
export function add(x: number, y: number): number {
  return x + y;
}

/**
 * A shape.
 */
@Component({ selector: "x" })
export class Shape {
  private name = "s";

/** The area. */
  area(): number {
    if (this.name === "}") { return 0; }
    return 1;
  }

/** Doubles. */
export const double = (n: number): number => {
  return n * 2;
};
